package com.sari.subtitle

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.text.InputType
import android.widget.ArrayAdapter
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.google.android.material.appbar.MaterialToolbar
import com.google.android.material.button.MaterialButton
import com.google.android.material.materialswitch.MaterialSwitch
import com.google.android.material.slider.Slider
import com.google.android.material.textfield.MaterialAutoCompleteTextView
import com.google.android.material.textfield.TextInputEditText
import kotlinx.coroutines.launch

class SettingsActivity:AppCompatActivity(){
    private lateinit var provider:MaterialAutoCompleteTextView;private lateinit var sttProvider:MaterialAutoCompleteTextView;private lateinit var speechKey:TextInputEditText;private lateinit var deepgramKey:TextInputEditText;private lateinit var openAiKey:TextInputEditText;private lateinit var translationKey:TextInputEditText;private lateinit var sourceLang:TextInputEditText;private lateinit var targetLang:TextInputEditText;private lateinit var speechLang:TextInputEditText;private lateinit var email:TextInputEditText;private lateinit var contextPrompt:TextInputEditText;private lateinit var fontSize:Slider;private lateinit var opacity:Slider;private lateinit var fontValue:TextView;private lateinit var opacityValue:TextView;private lateinit var position:MaterialAutoCompleteTextView;private lateinit var contextAwareSwitch:MaterialSwitch;private lateinit var translationMemorySwitch:MaterialSwitch;private lateinit var glossary:TextInputEditText;private lateinit var quality:MaterialAutoCompleteTextView
    private val sttNames=listOf("Groq Whisper","Deepgram Nova-2","Vosk offline");private val translationNames=listOf("Groq","Google Cloud Translation","MyMemory","OpenAI GPT-4o-mini");private val qualityNames=listOf("سريع — Fast","متوازن — Balanced","بجودة بشرية — Human Quality");private val positions=listOf("أعلى — Top","وسط — Center","أسفل — Bottom")
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContentView(R.layout.activity_settings);try{findViewById<MaterialToolbar>(R.id.settingsToolbar).apply{setNavigationOnClickListener{finish()};setOnMenuItemClickListener{if(it.itemId==R.id.action_save){saveSettings();true}else false}};provider=findViewById(R.id.providerSpinner);sttProvider=findViewById(R.id.sttProviderSpinner);speechKey=findViewById(R.id.speechKeyInput);deepgramKey=findViewById(R.id.deepgramKeyInput);openAiKey=findViewById(R.id.openAiKeyInput);translationKey=findViewById(R.id.translationKeyInput);sourceLang=findViewById(R.id.sourceLanguageInput);targetLang=findViewById(R.id.targetLanguageInput);speechLang=findViewById(R.id.speechLanguageInput);email=findViewById(R.id.emailInput);contextPrompt=findViewById(R.id.contextPromptInput);fontSize=findViewById(R.id.fontSizeSeek);opacity=findViewById(R.id.opacitySeek);fontValue=findViewById(R.id.fontSizeValue);opacityValue=findViewById(R.id.opacityValue);position=findViewById(R.id.positionSpinner);contextAwareSwitch=findViewById(R.id.contextAwareSwitch);translationMemorySwitch=findViewById(R.id.translationMemorySwitch);glossary=findViewById(R.id.glossaryInput);quality=findViewById(R.id.qualitySpinner)
            setup(provider,translationNames);setup(sttProvider,sttNames);setup(quality,qualityNames);setup(position,positions);fontSize.valueFrom=12f;fontSize.valueTo=48f;fontSize.stepSize=1f;opacity.valueFrom=0f;opacity.valueTo=100f;opacity.stepSize=1f;fontSize.addOnChangeListener{_,v,_->fontValue.text="${v.toInt()} sp"};opacity.addOnChangeListener{_,v,_->opacityValue.text="${v.toInt()}%"}
            findViewById<MaterialButton>(R.id.getGroqKeyButton).setOnClickListener{open("https://console.groq.com/keys")};findViewById<MaterialButton>(R.id.getDeepgramKeyButton).setOnClickListener{open("https://console.deepgram.com")};findViewById<MaterialButton>(R.id.testDeepgramButton).setOnClickListener{testDeepgram()};findViewById<MaterialButton>(R.id.testOpenAiButton).setOnClickListener{testOpenAi()};findViewById<MaterialButton>(R.id.getOpenAiKeyButton).setOnClickListener{open("https://platform.openai.com/api-keys")};findViewById<MaterialButton>(R.id.downloadVoskButton).setOnClickListener{downloadVosk()};
            runCatching{findViewById<MaterialButton>(R.id.providerDashboardButton).setOnClickListener{startActivity(android.content.Intent(this@SettingsActivity,ProviderDashboardActivity::class.java))}};findViewById<MaterialButton>(R.id.saveSettingsButton).setOnClickListener{saveSettings()}
            lifecycleScope.launch{val s=SettingsRepository(this@SettingsActivity).load();provider.setText(translationNames[s.provider.coerceIn(0,3)],false);sttProvider.setText(sttNames[s.sttProvider.coerceIn(0,2)],false);speechKey.setText(s.speechKey);deepgramKey.setText(s.deepgramKey);openAiKey.setText(s.openAiKey);translationKey.setText(s.translationKey);sourceLang.setText(s.sourceLanguage);targetLang.setText(s.targetLanguage);speechLang.setText(s.speechLanguage);email.setText(s.myMemoryEmail);contextPrompt.setText(s.contextPrompt);fontSize.value=s.fontSize.toFloat();opacity.value=s.opacity.toFloat();fontValue.text="${s.fontSize} sp";opacityValue.text="${s.opacity}%";position.setText(positions[s.subtitlePosition.coerceIn(0,2)],false);contextAwareSwitch.isChecked=s.contextAwareTranslation;translationMemorySwitch.isChecked=s.translationMemoryEnabled;glossary.setText(s.glossary);quality.setText(qualityNames[s.translationQuality.coerceIn(0,2)],false)}}catch(e:Exception){Toast.makeText(this,e.message?:"تعذر فتح الإعدادات",Toast.LENGTH_LONG).show()}}
    private fun setup(v:MaterialAutoCompleteTextView,items:List<String>){v.setAdapter(ArrayAdapter(this,android.R.layout.simple_dropdown_item_1line,items));v.setOnClickListener{v.showDropDown()};v.inputType=InputType.TYPE_NULL}
    private fun open(url:String){runCatching{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)))}}
    private fun testDeepgram(){lifecycleScope.launch{val ok=DeepgramClient(deepgramKey.text?.toString()?.trim().orEmpty()).testKey();Toast.makeText(this@SettingsActivity,if(ok)getString(R.string.key_valid) else getString(R.string.key_invalid),Toast.LENGTH_LONG).show()}}
    private fun testOpenAi(){lifecycleScope.launch{val ok=OpenAiClient(openAiKey.text?.toString()?.trim().orEmpty()).testKey();Toast.makeText(this@SettingsActivity,if(ok)getString(R.string.key_valid) else getString(R.string.key_invalid),Toast.LENGTH_LONG).show()}}
    private fun downloadVosk(){lifecycleScope.launch{try{findViewById<MaterialButton>(R.id.downloadVoskButton).isEnabled=false;ModelDownloader(this@SettingsActivity).downloadArabic{};Toast.makeText(this@SettingsActivity,R.string.vosk_ready,Toast.LENGTH_LONG).show()}catch(e:Exception){Toast.makeText(this@SettingsActivity,e.message?:getString(R.string.vosk_failed),Toast.LENGTH_LONG).show()}finally{findViewById<MaterialButton>(R.id.downloadVoskButton).isEnabled=true}}}
    private fun saveSettings(){lifecycleScope.launch{try{val s=SettingsRepository(this@SettingsActivity).load();SettingsRepository(this@SettingsActivity).save(provider=translationNames.indexOf(provider.text.toString()).coerceAtLeast(0),speechKey=speechKey.text?.toString()?.trim().orEmpty(),translationKey=translationKey.text?.toString()?.trim().orEmpty(),source=sourceLang.text?.toString()?.trim().orEmpty().ifBlank{"auto"},target=targetLang.text?.toString()?.trim().orEmpty().ifBlank{"ar"},font=fontSize.value.toInt(),opacity=opacity.value.toInt(),email=email.text?.toString()?.trim().orEmpty(),speechLanguage=speechLang.text?.toString()?.trim().orEmpty().ifBlank{"auto"},contextAwareTranslation=contextAwareSwitch.isChecked,translationMemoryEnabled=translationMemorySwitch.isChecked,glossary=glossary.text?.toString().orEmpty(),translationQuality=qualityNames.indexOf(quality.text.toString()).coerceIn(0,2),sttProvider=sttNames.indexOf(sttProvider.text.toString()).coerceIn(0,2),deepgramKey=deepgramKey.text?.toString()?.trim().orEmpty(),openAiKey=openAiKey.text?.toString()?.trim().orEmpty(),contextPrompt=contextPrompt.text?.toString().orEmpty(),subtitlePosition=positions.indexOf(position.text.toString()).coerceIn(0,2),calibrationMs=s.calibrationMs);Toast.makeText(this@SettingsActivity,R.string.settings_saved,Toast.LENGTH_SHORT).show();finish()}catch(e:Exception){Toast.makeText(this@SettingsActivity,e.message?:getString(R.string.settings_save_failed),Toast.LENGTH_LONG).show()}}}
}
